package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string   // PIC X(20) len=20 = SPACES
var WsACount int64   // PIC 99 len=2 = 0
var WsTotalA int64   // PIC 999 len=3 = 0
var WsCount int64    // PIC 999 len=3 = 0

var partFileRecords []PartRec
var partFileIdx int
var curRec PartRec

func init() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0
}

// ---- helpers ----

func loadPartFile() []PartRec {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		fmt.Fprintf(os.Stderr, "cannot open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	var recs []PartRec
	reader := bufio.NewReader(f)
	for {
		line, err := reader.ReadString('\n')
		hasNL := false
		if len(line) > 0 && line[len(line)-1] == '\n' {
			hasNL = true
			line = line[:len(line)-1]
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
		}
		if err != nil && err != io.EOF {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		if err == io.EOF && line == "" && !hasNL {
			break
		}
		// pad / truncate to record length 15
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		lbPart := line[0:8]
		lbRegion := line[8:11]
		lbSerialStr := line[11:15]
		var lbSerial int64
		trimmed := strings.TrimSpace(lbSerialStr)
		if trimmed != "" {
			digits := ""
			for _, c := range lbSerialStr {
				if c >= '0' && c <= '9' {
					digits += string(c)
				}
			}
			if digits != "" {
				v, _ := strconv.ParseInt(digits, 10, 64)
				lbSerial = v % 10000
			}
		} else {
			lbSerial = 0
		}
		recs = append(recs, PartRec{
			LbPart:   lbPart,
			LbRegion: lbRegion,
			LbSerial: lbSerial,
		})
		if err == io.EOF {
			break
		}
	}
	return recs
}

// ---- paragraphs ----

func ReadPara() {
	if partFileIdx >= len(partFileRecords) {
		WsEofFlag = "Y"
		return
	}
	curRec = partFileRecords[partFileIdx]
	partFileIdx++
}

func ProcessPara() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	cnt := strings.Count(curRec.LbPart, "A")
	WsACount = int64(cnt) % 100

	// STRING ... INTO WS-LABEL
	dest := []byte(WsLabel) // 20 spaces
	pos := 0
	writeSeg := func(seg string) {
		for i := 0; i < len(seg); i++ {
			if pos >= 20 {
				break
			}
			dest[pos] = seg[i]
			pos++
		}
	}
	seg1 := curRec.LbRegion
	if idx := strings.Index(seg1, " "); idx != -1 {
		seg1 = seg1[:idx]
	}
	writeSeg(seg1)
	writeSeg("-")
	seg3 := curRec.LbPart
	if idx := strings.Index(seg3, " "); idx != -1 {
		seg3 = seg3[:idx]
	}
	writeSeg(seg3)
	writeSeg("-")
	seg5 := fmt.Sprintf("%04d", curRec.LbSerial)
	writeSeg(seg5)
	WsLabel = string(dest)

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = (WsTotalA + WsACount) % 1000
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 1000

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	fmt.Printf("%s A=%02d\n", WsLabel, WsACount)

	// PERFORM READ-PARA
	ReadPara()
}

func SummaryPara() {
	fmt.Printf("LABELS: %03d A-TOTAL: %03d\n", WsCount, WsTotalA)
}

func MainPara() {
	partFileRecords = loadPartFile()
	partFileIdx = 0
	WsEofFlag = "N"
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	// CLOSE PART-FILE (no-op)
	SummaryPara()
}

func main() {
	MainPara()
}
